public class BillingDelegate {
    private BillingSession session;                        // cached remote reference
    public BillingDelegate() throws BillingException {
        try { session = ((BillingSessionHome) ServiceLocator.getInstance()
                .getHome("billing")).create(); }
        catch (ServiceLocatorException | CreateException e) { throw new BillingException("lookup failed", e); }
    }
    public Invoice createInvoice(CreateInvoice cmd) throws BillingException {
        try { return session.createInvoice(cmd); }
        catch (RemoteException e) { throw new BillingException("billing unavailable", e); }
    }
}
